// Submits the message the CRM already built, unchanged.
//
// WHY THIS IS A CODE NODE AND NOT THE "Send Email" NODE.
//
// n8n's emailSend node cannot do three things this reply path requires, and
// its own documentation says so: it "does not support setting headers like
// In-Reply-To and References, which are required for email threading", it
// exposes no way to set a Message-ID, and it gives nodemailer no `envelope`,
// so MAIL FROM is always derived from the From: header.
//
// Using it would produce replies that arrive as a NEW conversation in the
// recipient's client, and bounces that come back with no identifier attached
// and therefore correlate to nothing. Both failures are invisible from this
// side: the send succeeds, and nothing reports that threading was lost.
//
// So the CRM builds the complete RFC 5322 message and hands over the envelope
// separately. This node's entire job is MAIL FROM, RCPT TO, DATA.
//
// REQUIRES on the n8n container (or on the Task Runner, if you use one):
//   NODE_FUNCTION_ALLOW_EXTERNAL=nodemailer
// Without it, `require` is blocked and this node fails closed — which is the
// right direction: nothing is sent and the reply stays queued.

const nodemailer = require('nodemailer')

const reply = $input.item.json

// The private Docker mail network. Postfix trusts ONLY this n8n container's IP
// plus localhost, and has no listener reachable from the internet. Do not point
// this at a public address, and do not widen Postfix's mynetworks to make it
// work from somewhere else.
const transporter = nodemailer.createTransport({
  host: $env.DEVLAB_SMTP_HOST || '172.19.0.1',
  port: Number($env.DEVLAB_SMTP_PORT || 25),
  secure: false,
  // The hop to Postfix is over a private Docker network on the same host, and
  // Postfix presents a self-signed certificate there. TLS to the RECIPIENT is
  // negotiated by Postfix itself and is unaffected by this.
  tls: { rejectUnauthorized: false },
})

const info = await transporter.sendMail({
  // Both are required together. nodemailer does not parse the envelope out of
  // a raw message, and this envelope sender is the per-message VERP address
  // that lets a bounce find its way back to the right conversation.
  envelope: { from: reply.envelope.from, to: reply.envelope.to },
  raw: reply.raw,
})

return {
  json: {
    id: reply.id,
    providerMessageId: info.messageId || null,
    accepted: info.accepted || [],
    rejected: info.rejected || [],
  },
}
